return $input.all().map(item => {
  const data = item.json || {};
  const baseUrl = data.baseUrl || data.base_url || 'http://192.168.0.194:9000';

  if (!data.asset_id || !data.object_path || !data.bucket) {
    return {
      json: {
        ...data,
        promoted: false,
        url: null,
        reason: 'Asset not found or missing bucket/object_path'
      }
    };
  }

  return {
    json: {
      promoted: true,
      assetId: data.asset_id,
      avatar: data.avatar,
      scene: data.scene,
      assetType: data.asset_type,
      url: `${baseUrl}/${data.bucket}/${data.object_path}`,
      bucket: data.bucket,
      objectPath: data.object_path,
      mimeType: data.mime_type,
      status: data.status,
      isCanonical: data.is_canonical,
      canonicalGroup: data.canonical_group,
      demotedCount: data.demoted_count,
      sha256: data.sha256,
      createdAt: data.created_at
    }
  };
});
